    private func roundTrip(_ name:String,_ data:Data) throws -> Data {
        let decoder=CodableHelper.jsonDecoder,encoder=CodableHelper.jsonEncoder
        if name == "WorkoutControlView" { return try encoder.encode(decoder.decode(WorkoutControlView.self,from:data)) }
        return try encoder.encode(decoder.decode(WorkoutControlReceipt.self,from:data))
    }
    private func normalized(_ value:Any)->Any {
        if let fields=value as? [String:Any] {
            var result=fields.mapValues(normalized)
            if let actions=fields["allowedActions"] as? [String] {result["allowedActions"]=actions.sorted()}
            return result
        }
        if let items=value as? [Any] {return items.map(normalized)}
        return value
    }
    func testMissingNullZeroAndValueInBothNestedEnvelopes() throws {
        let all=try JSONSerialization.jsonObject(with:Data(fixtures.utf8)) as! [String:[[String:Any]]]
        XCTAssertEqual(all["positives"]!.count,98)
        for fixture in all["positives"]! {
            let name=fixture["name"] as! String,original=fixture["value"]!
            let encoded=try roundTrip(name,JSONSerialization.data(withJSONObject:original))
            XCTAssertEqual(try normalized(JSONSerialization.jsonObject(with:encoded)) as! NSDictionary,normalized(original) as! NSDictionary,fixture["label"] as! String)
            let again=try roundTrip(name,encoded)
            XCTAssertEqual(try normalized(JSONSerialization.jsonObject(with:again)) as! NSDictionary,normalized(original) as! NSDictionary,fixture["label"] as! String)
        }
    }
    func testUnknownEnumAndWrongTypesAreStillRefused() throws {
        let all=try JSONSerialization.jsonObject(with:Data(fixtures.utf8)) as! [String:[[String:Any]]]
        XCTAssertEqual(all["negatives"]!.count,24)
        for fixture in all["negatives"]! {
            let input=try JSONSerialization.data(withJSONObject:fixture["value"]!)
            XCTAssertThrowsError(try roundTrip(fixture["name"] as! String,input),fixture["label"] as! String)
        }
    }
